mapper.update:
update rental_refund_request
request_status = #{requestStatus}, review_notification_date = NOW()
where order_id = #{orderId}

mapper.select:
SELECT COUNT(rrr.refund_request_no) FROM rental_refund_request rrr inner join payment p on rrr.payment_completed_no = p.payment_completed_no inner join sell_products sp on p.sell_products_no = sp.sell_products_no inner join products pd on sp.products_no = pd.products_no
rrr.ent_ceo_no = #{entCeoNo}
AND rrr.request_status LIKE CONCAT('%', #{searchValue}, '%')

select rrr.cust_id, pd.products_nm, rrr.refund_reason, rrr.refund_date, rrr.request_status, rrr.review_notification_date, rrr.payment_key, rrr.order_id from rental_refund_request rrr inner join payment p on rrr.payment_completed_no = p.payment_completed_no inner join sell_products sp on p.sell_products_no = sp.sell_products_no inner join products pd on sp.products_no = pd.products_no
rrr.ent_ceo_no = #{entCeoNo}
AND rrr.request_status LIKE CONCAT('%', #{searchValue}, '%')
order by rrr.refund_date DESC LIMIT #{pageable.rowPerPage} OFFSET #{pageable.offset}
